    n = int(data[0])
    par = [int(x) for x in data[1:1 + n]]
    p = int(data[1 + n]); q = int(data[2 + n])
    def depth(x):
        d = 0
        while par[x] != -1:
            x = par[x]; d += 1
        return d
    dp, dq = depth(p), depth(q)
    while dp > dq:
        p = par[p]; dp -= 1
    while dq > dp:
        q = par[q]; dq -= 1
    while p != q:
        p = par[p]; q = par[q]
