def build(rng, n, mode):
    par = [-1] * n
    cnt = [0] * n
    for i in range(1, n):
        if mode == 'bal':
            j = (i - 1) // 2
        elif mode == 'deep' and cnt[i - 1] < 2 and rng.random() < 0.97:
            j = i - 1
        else:
            while True:
                j = rng.randrange(i)
                if cnt[j] < 2:
                    break
        par[i] = j; cnt[j] += 1
    return par

def make(rng, n, mode, rel='any'):
    par = build(rng, n, mode)
    perm = list(range(n)); rng.shuffle(perm)
    npar = [-1] * n
    for i in range(n):
        npar[perm[i]] = -1 if par[i] == -1 else perm[par[i]]
    p = rng.randrange(n)
    if rel == 'anc':
        # q is a descendant of p (or deeper on the same path)
        anc_of = par
        q = rng.randrange(n)
        # walk q up randomly to get an ancestor, make p that ancestor
        x = q
        steps = rng.randrange(0, 50)
        while steps and anc_of[x] != -1:
            x = anc_of[x]; steps -= 1
        p, q = x, q
        if p == q:
            q = rng.randrange(n)
            while q == p:
                q = rng.randrange(n)
        # make sure at least tests remain valid even if not ancestor
        p, q = perm[p], perm[q]
    else:
        q = rng.randrange(n)
        while q == p:
            q = rng.randrange(n)
        p, q = perm[p], perm[q]
    return str(n) + '\n' + ' '.join(map(str, npar)) + '\n' + str(p) + ' ' + str(q)

def gen(rng):
    t = ['2\n-1 0\n0 1', '2\n1 -1\n0 1', '3\n-1 0 0\n1 2', '3\n-1 0 1\n0 2']
    for n in (3, 4, 5, 7, 9, 12, 20):
        for mode in ('rand', 'deep', 'bal'):
            t.append(make(rng, n, mode))
        t.append(make(rng, n, 'rand', 'anc'))
    t.append(make(rng, 100000, 'deep'))
    t.append(make(rng, 100000, 'deep', 'anc'))
    t.append(make(rng, 100000, 'bal'))
    t.append(make(rng, 100000, 'rand'))
    return t

